    }
    if (utcMs.present) {
      map['utc_ms'] = Variable<int>(utcMs.value);
    }
    if (rowid.present) {
      map['rowid'] = Variable<int>(rowid.value);
    }
    return map;
  }

  @override
  String toString() {
    return (StringBuffer('ActivityEventsCompanion(')
          ..write('id: $id, ')
          ..write('sessionId: $sessionId, ')
          ..write('localDate: $localDate, ')
          ..write('playedWallMs: $playedWallMs, ')
          ..write('utcMs: $utcMs, ')
          ..write('rowid: $rowid')
          ..write(')'))
        .toString();
  }
}

